def calculate_average(grades):
    """Calculate the average of a list of numbers."""
    return sum(grades) / len(grades)

def main():
    student_grades = {}

    # Get student name and grades
    student_name = input("Enter student's name: ")
    student_grades[student_name] = {}

    for subject in ["math", "science", "english"]:
        grade = int(input(f"Enter grade for {subject}: "))
        student_grades[student_name][subject] = grade

    # Calculate and store average grade
    average_grade = calculate_average(list(student_grades[student_name].values()))
    student_grades[student_name]["average"] = average_grade

    # Print results
    print(f"{student_name}'s grades:")
    for subject, grade in student_grades[student_name].items():
        print(f"\t{subject} - {grade}")
    print(f"\nAverage - {average_grade:.2f}")

if __name__ == "__main__":
    main()
```

This program defines a helper function `calculate_average` to calculate the average of a list of numbers. The main part of the program gets the student's name and grades, calculates the average, and prints the results. The output will be similar to the sample input/output you provided.
